          { title: "\u0627\u0644\u0623\u0645\u0646 \u0648\u0627\u0644\u0627\u0633\u062A\u0642\u0631\u0627\u0631", desc: "\u0628\u064A\u0626\u0629 \u0647\u0627\u062F\u0626\u0629 \u0648\u0622\u0645\u0646\u0629\u060C \u0636\u0631\u0648\u0631\u064A\u0629 \u0644\u062A\u0642\u0627\u0639\u062F \u0647\u0627\u062F\u0626 \u0648\u0645\u064F\u0648\u0641\u0651\u0631.", icon: "shield" }
