          "\u063A\u064A\u0627\u0628 \u0627\u0644\u062A\u0646\u0633\u064A\u0642 \u0648\u0627\u0644\u062A\u0639\u0627\u0648\u0646 \u0628\u064A\u0646 \u0627\u0644\u0646\u0627\u062F\u064A \u0627\u0644\u0633\u064A\u0627\u0631\u0627\u062A\u064A \u0627\u0644\u062A\u0648\u0646\u0633\u064A (\u0627\u0644\u0645\u0645\u062B\u0644 \u0627\u0644\u062D\u0635\u0631\u064A \u0644\u0640 FIA) \u0648\u0627\u0644\u0627\u062A\u062D\u0627\u062F \u0627\u0644\u062A\u0648\u0646\u0633\u064A \u0644\u0644\u0631\u064A\u0627\u0636\u0627\u062A \u0627\u0644\u0622\u0644\u064A\u0629\u060C \u0645\u0645\u0627 \u064A\u0645\u0646\u0639 \u062A\u0646\u0638\u064A\u0645 \u0627\u0644\u0631\u0627\u0644\u064A\u0627\u062A \u0648\u063A\u064A\u0631\u0647\u0627 \u0645\u0646 \u0627\u0644\u0641\u0639\u0627\u0644\u064A\u0627\u062A."
