        actionsBody: "\u0625\u062C\u0631\u0627\u0621\u0627\u062A \u0645\u0637\u0644\u0648\u0628\u0629: \u062A\u0631\u0648\u064A\u062C \u0627\u0644\u0642\u0637\u0627\u0639 \u0639\u0628\u0631 \u0634\u0628\u0643\u0627\u062A \u0645\u062A\u062E\u0635\u0635\u0629: \u0645\u0639\u0627\u0631\u0636 \u0648\u0635\u0627\u0644\u0648\u0646\u0627\u062A \u0645\u062A\u062E\u0635\u0635\u0629 \u0648\u0645\u062C\u0644\u0627\u062A \u0648\u062F\u0639\u0648\u0627\u062A \u0635\u062D\u0627\u0641\u0629 \u0648\u0648\u0633\u0627\u0626\u0644 \u0625\u0639\u0644\u0627\u0645 \u0645\u062A\u062E\u0635\u0635\u0629\u2026 \u0648\u0641\u0648\u0642 \u0643\u0644 \u0630\u0644\u0643 \u0625\u064A\u062C\u0627\u062F \u062A\u0633\u0648\u064A\u0629 \u0628\u064A\u0646 \u0627\u0644\u0646\u0627\u062F\u064A \u0627\u0644\u0633\u064A\u0627\u0631\u0627\u062A\u064A \u0627\u0644\u062A\u0648\u0646\u0633\u064A \u0648\u0627\u062A\u062D\u0627\u062F \u0627\u0644\u0631\u064A\u0627\u0636\u0627\u062A \u0627\u0644\u0622\u0644\u064A\u0629.",
